using System.IO;using System.IO.Compression;using System.Text;
namespace FaceAssets;
// Streamed, bounded TES5 record reader. Resolves HDPT and TXST only; never executes plugin data.
public sealed class HeadPartRecords {
 public sealed class Record {public string Id="",Source="",Kind="";public uint Flags;public List<(string type,byte[] data)> Fields=[];public string Text(string tag)=>Encoding.UTF8.GetString(Fields.FirstOrDefault(f=>f.type==tag).data??[]).TrimEnd('\0');public uint Number(string tag)=>Fields.FirstOrDefault(f=>f.type==tag).data is {Length:>=4} b?BitConverter.ToUInt32(b):0;public Dictionary<int,string> Tris(){var result=new Dictionary<int,string>();int key=-1;foreach(var (t,b) in Fields){if(t=="NAM0"&&b.Length==4)key=(int)BitConverter.ToUInt32(b);if(t=="NAM1"&&key>=0)result[key]=Encoding.UTF8.GetString(b).TrimEnd('\0');}return result;}}
 readonly Dictionary<string,List<Record>> byPlugin=new(StringComparer.OrdinalIgnoreCase);
 readonly GameResources resources;readonly HashSet<string> loaded=new(StringComparer.OrdinalIgnoreCase);readonly Dictionary<string,Record> records=new(StringComparer.OrdinalIgnoreCase);readonly Dictionary<string,List<string>> masters=new(StringComparer.OrdinalIgnoreCase);
 public IEnumerable<string> LoadedPlugins=>byPlugin.Keys;
 public IEnumerable<Record> Records=>records.Values;
 public HeadPartRecords(GameResources r){resources=r;}
 public string Reference(string plugin,uint id){if(!masters.TryGetValue(plugin,out var m))throw new InvalidDataException("Plugin header not loaded: "+plugin);uint index=id>>24;if(index>m.Count)throw new InvalidDataException("Invalid plugin master index");return(index==m.Count?plugin:m[(int)index])+"|"+(id&0xffffff).ToString("X6");}
 public static string Canonical(string id){var pieces=id.Split('|');if(pieces.Length!=2||pieces[0].IndexOfAny(Path.GetInvalidFileNameChars())>=0||!uint.TryParse(pieces[1],System.Globalization.NumberStyles.HexNumber,null,out uint n)||n>0xffffff)throw new InvalidDataException("Invalid formIdentifier: "+id);return pieces[0]+"|"+n.ToString("X6");}
 public Record? Get(string id){id=Canonical(id);Load(id.Split('|')[0]);return records.GetValueOrDefault(id);}
 public void Load(string plugin){if(!loaded.Add(plugin))return;string? path=resources.Find(plugin);if(path==null){resources.Notes.Add("Plugin unavailable: "+plugin+". Check the selected Data directory and active MO2 profile; no replacement was guessed.");return;}using var stream=File.OpenRead(path);using var r=new BinaryReader(stream);if(stream.Length>2L*1024*1024*1024)throw new InvalidDataException("Plugin size exceeds 2 GiB");int count=0;masters[plugin]=[];byPlugin[plugin]=[];
 void Scan(long end,int depth){if(depth>32)throw new InvalidDataException("Plugin group depth");while(stream.Position<end){long start=stream.Position;if(end-start<24)throw new InvalidDataException("Truncated plugin header");string kind=Encoding.ASCII.GetString(r.ReadBytes(4));uint size=r.ReadUInt32();if(kind=="GRUP"){var label=Encoding.ASCII.GetString(r.ReadBytes(4));uint type=r.ReadUInt32();stream.Position=start+24;long stop=start+size;if(size<24||stop>end)throw new InvalidDataException("Plugin group bounds");if(type!=0||label is "HDPT" or "TXST")Scan(stop,depth+1);stream.Position=stop;continue;}uint flags=r.ReadUInt32(),fid=r.ReadUInt32();stream.Position=start+24;long finish=stream.Position+size;if(finish>end)throw new InvalidDataException("Plugin record bounds");if(kind is not ("TES4" or "HDPT" or "TXST")){stream.Position=finish;continue;}if(++count>100000||size>8*1024*1024)throw new InvalidDataException("Plugin record budget");byte[] bytes=r.ReadBytes((int)size);if((flags&0x40000)!=0){if(bytes.Length<4)throw new InvalidDataException("Compressed record header");int n=BitConverter.ToInt32(bytes);if(n<0||n>16*1024*1024)throw new InvalidDataException("Expanded record budget");using var z=new ZLibStream(new MemoryStream(bytes,4,bytes.Length-4),CompressionMode.Decompress);var expanded=new byte[n];z.ReadExactly(expanded);if(z.ReadByte()!=-1)throw new InvalidDataException("Expanded record size");bytes=expanded;}var fields=new List<(string,byte[])>();using(var sr=new BinaryReader(new MemoryStream(bytes))){uint extended=0;while(sr.BaseStream.Position<bytes.Length){if(bytes.Length-sr.BaseStream.Position<6)throw new InvalidDataException("Truncated subrecord");string tag=Encoding.ASCII.GetString(sr.ReadBytes(4));uint n=sr.ReadUInt16();if(tag=="XXXX"){if(n!=4)throw new InvalidDataException("XXXX size");extended=sr.ReadUInt32();continue;}if(extended>0){n=extended;extended=0;}if(n>bytes.Length-sr.BaseStream.Position)throw new InvalidDataException("Subrecord bounds");fields.Add((tag,sr.ReadBytes((int)n)));}}
 if(kind=="TES4"){masters[plugin]=fields.Where(f=>f.Item1=="MAST").Select(f=>Encoding.UTF8.GetString(f.Item2).TrimEnd('\0')).ToList();foreach(var master in masters[plugin])Load(master);continue;}string id=Reference(plugin,fid);var parsed=new Record{Id=id,Kind=kind,Flags=flags,Source=plugin,Fields=fields};byPlugin[plugin].Add(parsed);records[id]=parsed;}}
 Scan(stream.Length,0);
 }
 public void Overrides(IEnumerable<string> plugins){var order=plugins.Distinct(StringComparer.OrdinalIgnoreCase).ToArray();foreach(var p in order)try{Load(p);}catch(Exception e){resources.Notes.Add("Plugin record scan: "+p+": "+e.Message);}foreach(var p in order)if(byPlugin.TryGetValue(p,out var own))foreach(var record in own)records[record.Id]=record;}
}
